type SortDirection = "asc" | "desc"

type SortSpec = { field: string; direction: SortDirection }

type PagePosition = { page: number } | { cursor: string | null; direction: "forward" | "backward" }

type PageRequest<F> = {
  filter: F
  sort: readonly SortSpec[]
  size: number
  position: PagePosition
}

type PageResult<T> = {
  items: T[]
  total?: number
  totalEstimate?: number
  hasMore?: boolean
  hasPrevious?: boolean
  nextCursor?: string | null
  prevCursor?: string | null
}

type SourceContext = { signal: AbortSignal }

type SourceCapabilities = {
  position: "page" | "cursor"
  total?: "exact" | "estimate" | "none"
  maxPageSize?: number
}

type PageSource<T, F = unknown> = {
  /** The query key prefix: every query of this source starts with it, so invalidating it refreshes them all. */
  key: readonly unknown[]
  getId(item: T): string
  capabilities: SourceCapabilities
  fetchPage(request: PageRequest<F>, context: SourceContext): Promise<PageResult<T>>
  /** A count of its own, run as a separate query that never holds back the rows. */
  fetchTotal?(filter: F, context: SourceContext): Promise<number>
}

type Navigation = "pages" | "prev-next" | "load-more" | "infinite"
type NavigationMode = Navigation | "auto"

/** What the source said about the size of the result: exact, estimated or unknown. */
type TotalInfo = { kind: "exact"; value: number } | { kind: "estimate"; value: number } | { kind: "none" }

function isPagePosition(position: PagePosition): position is { page: number } {
  return "page" in position
}

function totalOf(result: PageResult<unknown> | undefined, counted?: number): TotalInfo {
  if (result?.total !== undefined && Number.isFinite(result.total)) return { kind: "exact", value: result.total }
  if (counted !== undefined && Number.isFinite(counted)) return { kind: "exact", value: counted }
  if (result?.totalEstimate !== undefined && Number.isFinite(result.totalEstimate))
    return { kind: "estimate", value: result.totalEstimate }
  return { kind: "none" }
}

/**
 * `"auto"` follows what the source gives: page numbers with an exact total, previous and next with an estimate or
 * only `hasMore`, and load more for a cursor. Before the first result it goes by the declared capabilities.
 */
function resolveNavigation(
  capabilities: SourceCapabilities,
  mode: NavigationMode = "auto",
  total: TotalInfo = { kind: "none" },
): Navigation {
  if (mode !== "auto") return mode
  if (capabilities.position === "cursor") return "load-more"
  if (total.kind === "exact") return "pages"
  if (total.kind === "none" && capabilities.total === "exact") return "pages"
  return "prev-next"
}

function pageCountOf(total: number, size: number) {
  return size > 0 ? Math.max(1, Math.ceil(total / size)) : 1
}

/** Caps a page size at the source's `maxPageSize` and keeps it a positive integer. */
function capPageSize(size: number, capabilities: SourceCapabilities) {
  const whole = Number.isFinite(size) ? Math.max(1, Math.trunc(size)) : 1
  return capabilities.maxPageSize === undefined ? whole : Math.min(whole, capabilities.maxPageSize)
}

function capPageSizes(sizes: readonly number[], capabilities: SourceCapabilities) {
  return [...new Set(sizes.map((size) => capPageSize(size, capabilities)))].toSorted((a, b) => a - b)
}

type PageRange = { from: number; to: number; total: TotalInfo }

type PageStatusLabels = {
  /** "Showing 21–40 of 312", "Showing 21–40 of about 300" or "Showing 21–40". */
  range: (range: PageRange) => string
  empty: string
  loading: string
}

const numberFormat = new Intl.NumberFormat("en-US")

const pageStatusLabels: PageStatusLabels = {
  range: ({ from, to, total }) => {
    const shown = `Showing ${numberFormat.format(from)}–${numberFormat.format(to)}`
    if (total.kind === "exact") return `${shown} of ${numberFormat.format(total.value)}`
    if (total.kind === "estimate") return `${shown} of about ${numberFormat.format(total.value)}`
    return shown
  },
  empty: "No results",
  loading: "Loading…",
}

/** The first and last row shown, 1-based, for the live region. `offset` is how many rows come before the page. */
function pageRange(offset: number, count: number, total: TotalInfo): PageRange | undefined {
  if (count === 0) return undefined
  return { from: offset + 1, to: offset + count, total }
}

type ParamValue = string | number | boolean | null | undefined
type ParamsInit =
  | URLSearchParams
  | Iterable<readonly [string, string]>
  | Readonly<Record<string, ParamValue | readonly ParamValue[]>>

function appendParams(target: URLSearchParams, init: ParamsInit | undefined) {
  if (init === undefined) return target
  const entries: Iterable<readonly [string, unknown]> =
    init instanceof URLSearchParams || Symbol.iterator in init
      ? (init as Iterable<readonly [string, string]>)
      : Object.entries(init)
  for (const [name, value] of entries) {
    for (const item of Array.isArray(value) ? (value as unknown[]) : [value]) {
      if (item === undefined || item === null) continue
      target.append(name, String(item as string | number | boolean))
    }
  }
  return target
}

type SortStyle = "comma" | "dot" | "sign" | ((sort: readonly SortSpec[], params: URLSearchParams) => void)

/**
 * How sort goes on the wire: `"comma"` repeats `sort=name,asc` (Spring), `"dot"` writes `sort=name.asc,id.desc`,
 * `"sign"` writes `sort=name,-id` (JSON:API).
 */
function writeSort(params: URLSearchParams, sort: readonly SortSpec[], style: SortStyle = "comma", name = "sort") {
  if (typeof style === "function") return style(sort, params)
  if (sort.length === 0) return
  if (style === "comma") for (const spec of sort) params.append(name, `${spec.field},${spec.direction}`)
  else if (style === "dot") params.set(name, sort.map((spec) => `${spec.field}.${spec.direction}`).join(","))
  else params.set(name, sort.map((spec) => (spec.direction === "desc" ? `-${spec.field}` : spec.field)).join(","))
}

/** A failed HTTP response. `status` is what DataProvider's retry reads: a 4xx is never retried. */
class HttpError extends Error {
  readonly status: number
  readonly response: Response | undefined

  constructor(status: number, message?: string, response?: Response) {
    super(message ?? `Request failed with status ${String(status)}`)
    this.name = "HttpError"
    this.status = status
    this.response = response
  }
}

/** Reads a response's JSON body, or throws an `HttpError` with its status. */
async function readJson<Raw>(response: Response): Promise<Raw> {
  if (!response.ok) throw new HttpError(response.status, response.statusText || undefined, response)
  return (await response.json()) as Raw
}

function abortError(signal: AbortSignal): unknown {
  return signal.reason ?? new DOMException("The operation was aborted.", "AbortError")
}

function isAbortError(error: unknown) {
  return error instanceof DOMException && error.name === "AbortError"
}

export {
  abortError,
  appendParams,
  capPageSize,
  capPageSizes,
  HttpError,
  isAbortError,
  isPagePosition,
  pageCountOf,
  pageRange,
  pageStatusLabels,
  readJson,
  resolveNavigation,
  totalOf,
  writeSort,
}
export type {
  Navigation,
  NavigationMode,
  PagePosition,
  PageRange,
  PageRequest,
  PageResult,
  PageSource,
  PageStatusLabels,
  ParamsInit,
  ParamValue,
  SortDirection,
  SortSpec,
  SortStyle,
  SourceCapabilities,
  SourceContext,
  TotalInfo,
}

import {
  appendParams,
  isPagePosition,
  writeSort,
  type PageRequest,
  type PageResult,
  type PageSource,
  type ParamsInit,
  type SortStyle,
  type SourceCapabilities,
  type SourceContext,
} from "@/lib/page-source"

/** What an adapter hands your `request`: the query to send, and the request it came from. */
type RestCall<F> = {
  params: URLSearchParams
  /** `params` as a query string, without the `?`. */
  query: string
  request: PageRequest<F>
  signal: AbortSignal
}

type RestSourceOptions<T, F, Raw> = {
  key: readonly unknown[]
  getId: (item: T) => string
  /** Sends the call: `fetch(\`/api/tasks?${call.query}\`, { signal: call.signal }).then(readJson)`. */
  request: (call: RestCall<F>) => Promise<Raw>
  /** The filter as query params, usually a serializer's output. */
  params?: (filter: F) => ParamsInit
  sortStyle?: SortStyle
  sortParam?: string
  maxPageSize?: number
  /** Whether responses carry an exact total. Default `"exact"`. */
  total?: SourceCapabilities["total"]
  fetchTotal?: (filter: F, context: SourceContext) => Promise<number>
}

function pageOf<F>(request: PageRequest<F>) {
  if (!isPagePosition(request.position)) throw new TypeError("This source pages by number; it got a cursor.")
  return Math.max(1, Math.trunc(request.position.page))
}

function callOf<F>(request: PageRequest<F>, context: SourceContext, params: URLSearchParams): RestCall<F> {
  return { params, query: params.toString(), request, signal: context.signal }
}

function baseParams<T, F, Raw>(options: RestSourceOptions<T, F, Raw>, request: PageRequest<F>) {
  const params = appendParams(new URLSearchParams(), options.params?.(request.filter))
  writeSort(params, request.sort, options.sortStyle, options.sortParam)
  return params
}

function asResult<T>(raw: unknown, where: string): PageResult<T> {
  if (typeof raw !== "object" || raw === null || !Array.isArray((raw as { items?: unknown }).items))
    throw new TypeError(`${where} expected { items, total? }; pass \`read\` to map your response.`)
  return raw as PageResult<T>
}

// Without a total, a full page is taken to mean there may be more; a short one is the last.
function withPaging<T>(result: PageResult<T>, page: number, size: number): PageResult<T> {
  const total = result.total ?? result.totalEstimate
  return {
    ...result,
    hasMore: result.hasMore ?? (total === undefined ? result.items.length >= size : page * size < total),
    hasPrevious: result.hasPrevious ?? page > 1,
  }
}

function source<T, F>(
  options: RestSourceOptions<T, F, unknown>,
  capabilities: SourceCapabilities,
  fetchPage: PageSource<T, F>["fetchPage"],
): PageSource<T, F> {
  return {
    key: options.key,
    getId: options.getId,
    capabilities,
    fetchPage,
    ...(options.fetchTotal ? { fetchTotal: options.fetchTotal } : {}),
  }
}

type PagedSourceOptions<T, F, Raw> = RestSourceOptions<T, F, Raw> & {
  /** The first page's number on the wire. Default 1. */
  base?: 0 | 1
  pageParam?: string
  sizeParam?: string
  /** Maps the response; by default it must be `{ items, total?, hasMore? }`. */
  read?: (raw: Raw, request: PageRequest<F>) => PageResult<T>
}

/** `?page=2&size=25`, 1-based unless `base: 0`. */
function pagedSource<T, F = unknown, Raw = PageResult<T>>(options: PagedSourceOptions<T, F, Raw>): PageSource<T, F> {
  const { base = 1, pageParam = "page", sizeParam = "size" } = options
  return source(
    options as RestSourceOptions<T, F, unknown>,
    { position: "page", total: options.total ?? "exact", maxPageSize: options.maxPageSize },
    async (request, context) => {
      const page = pageOf(request)
      const params = baseParams(options, request)
      params.set(pageParam, String(page - 1 + base))
      params.set(sizeParam, String(request.size))
      const raw = await options.request(callOf(request, context, params))
      const result = options.read ? options.read(raw, request) : asResult<T>(raw, "pagedSource")
      return withPaging(result, page, request.size)
    },
  )
}

type OffsetSourceOptions<T, F, Raw> = RestSourceOptions<T, F, Raw> & {
  offsetParam?: string
  limitParam?: string
  read?: (raw: Raw, request: PageRequest<F>) => PageResult<T>
}

/** `?offset=20&limit=20`: the page number becomes an offset. */
function offsetSource<T, F = unknown, Raw = PageResult<T>>(options: OffsetSourceOptions<T, F, Raw>): PageSource<T, F> {
  const { offsetParam = "offset", limitParam = "limit" } = options
  return source(
    options as RestSourceOptions<T, F, unknown>,
    { position: "page", total: options.total ?? "exact", maxPageSize: options.maxPageSize },
    async (request, context) => {
      const page = pageOf(request)
      const params = baseParams(options, request)
      params.set(offsetParam, String((page - 1) * request.size))
      params.set(limitParam, String(request.size))
      const raw = await options.request(callOf(request, context, params))
      const result = options.read ? options.read(raw, request) : asResult<T>(raw, "offsetSource")
      return withPaging(result, page, request.size)
    },
  )
}

/** Spring Data's `Page<T>` as JSON, or the `PagedModel` that `@EnableSpringDataWebSupport(pageSerializationMode = VIA_DTO)` writes. */
type SpringPage<T> = {
  content: T[]
  totalElements?: number
  totalPages?: number
  number?: number
  size?: number
  first?: boolean
  last?: boolean
  page?: { size: number; number: number; totalElements: number; totalPages: number }
}

/** Spring Data's `Slice<T>`: no count query, only whether another slice follows. */
type SpringSlice<T> = {
  content: T[]
  number?: number
  size?: number
  first?: boolean
  last?: boolean
  hasNext?: boolean
}

type SpringSourceOptions<T, F, Raw> = Omit<RestSourceOptions<T, F, Raw>, "sortStyle" | "total"> & {
  /** Where the page sits in your response, when it isn't the body itself. */
  select?: (raw: Raw) => SpringPage<T>
}

function springContent<T>(raw: unknown, where: string): SpringPage<T> {
  if (typeof raw !== "object" || raw === null || !Array.isArray((raw as { content?: unknown }).content))
    throw new TypeError(`${where} expected a Spring page with \`content\`; pass \`select\` to find it.`)
  return raw as SpringPage<T>
}

function springParams<T, F, Raw>(options: SpringSourceOptions<T, F, Raw>, request: PageRequest<F>) {
  const params = appendParams(new URLSearchParams(), options.params?.(request.filter))
  writeSort(params, request.sort, "comma", options.sortParam)
  params.set("page", String(pageOf(request) - 1))
  params.set("size", String(request.size))
  return params
}

/** Spring Data REST and `Pageable` controllers: `?page=0&size=25&sort=name,asc`, read from `Page<T>` or `PagedModel`. */
function springPageSource<T, F = unknown, Raw = SpringPage<T>>(
  options: SpringSourceOptions<T, F, Raw>,
): PageSource<T, F> {
  return source(
    options as RestSourceOptions<T, F, unknown>,
    { position: "page", total: "exact", maxPageSize: options.maxPageSize },
    async (request, context) => {
      const raw = await options.request(callOf(request, context, springParams(options, request)))
      const page = options.select ? options.select(raw) : springContent<T>(raw, "springPageSource")
      const total = page.page?.totalElements ?? page.totalElements
      const number = page.page?.number ?? page.number ?? pageOf(request) - 1
      const totalPages = page.page?.totalPages ?? page.totalPages
      return {
        items: page.content,
        total,
        hasMore: page.last === undefined ? totalPages !== undefined && number + 1 < totalPages : !page.last,
        hasPrevious: page.first === undefined ? number > 0 : !page.first,
      }
    },
  )
}

/** A Spring `Slice<T>`: previous and next only, since it has no total. */
function springSliceSource<T, F = unknown, Raw = SpringSlice<T>>(
  options: Omit<SpringSourceOptions<T, F, Raw>, "select"> & { select?: (raw: Raw) => SpringSlice<T> },
): PageSource<T, F> {
  return source(
    options as RestSourceOptions<T, F, unknown>,
    { position: "page", total: "none", maxPageSize: options.maxPageSize },
    async (request, context) => {
      const raw = await options.request(callOf(request, context, springParams(options, request)))
      const slice = options.select
        ? options.select(raw)
        : (springContent<T>(raw, "springSliceSource") as SpringSlice<T>)
      const number = slice.number ?? pageOf(request) - 1
      return {
        items: slice.content,
        hasMore: slice.hasNext ?? (slice.last === undefined ? slice.content.length >= request.size : !slice.last),
        hasPrevious: slice.first === undefined ? number > 0 : !slice.first,
      }
    },
  )
}

export { offsetSource, pagedSource, springPageSource, springSliceSource }
export type {
  OffsetSourceOptions,
  PagedSourceOptions,
  RestCall,
  RestSourceOptions,
  SpringPage,
  SpringSlice,
  SpringSourceOptions,
}

import {
  appendParams,
  HttpError,
  isPagePosition,
  writeSort,
  type PageRequest,
  type PageResult,
  type PageSource,
  type ParamsInit,
  type SortStyle,
  type SourceContext,
} from "@/lib/page-source"
import type { RestCall } from "@/lib/page-source-rest"

type CursorPosition = { cursor: string | null; direction: "forward" | "backward" }

function cursorOf<F>(request: PageRequest<F>): CursorPosition {
  if (isPagePosition(request.position)) throw new TypeError("This source pages by cursor; it got a page number.")
  return request.position
}

type CursorSourceOptions<T, F, Raw> = {
  key: readonly unknown[]
  getId: (item: T) => string
  request: (call: RestCall<F>) => Promise<Raw>
  params?: (filter: F) => ParamsInit
  sortStyle?: SortStyle
  sortParam?: string
  /** The param a forward cursor goes in. Default `"cursor"`. */
  afterParam?: string
  /** The param a backward cursor goes in. Default `"before"`. */
  beforeParam?: string
  sizeParam?: string
  maxPageSize?: number
  /**
   * Keyset paging: the cursor is built from the last (or first) row's sort key, and one row more than the page is
   * asked for, to know whether another page follows. The server returns a backward page in display order.
   */
  keyset?: { cursor: (item: T) => string }
  /** Maps the response; by default `{ items, nextCursor?, prevCursor?, hasMore?, hasPrevious? }`. */
  read?: (raw: Raw, request: PageRequest<F>) => PageResult<T>
  fetchTotal?: (filter: F, context: SourceContext) => Promise<number>
}

function keysetResult<T>(
  items: T[],
  size: number,
  position: CursorPosition,
  cursor: (item: T) => string,
): PageResult<T> {
  const extra = items.length > size
  const forward = position.direction === "forward"
  // The extra row sits beyond the page: after it going forward, before it going backward.
  const page = extra ? (forward ? items.slice(0, size) : items.slice(items.length - size)) : items
  const first = page[0]
  const last = page.at(-1)
  const hasMore = forward ? extra : true
  const hasPrevious = forward ? position.cursor !== null : extra
  return {
    items: page,
    hasMore,
    hasPrevious,
    nextCursor: hasMore && last !== undefined ? cursor(last) : null,
    prevCursor: hasPrevious && first !== undefined ? cursor(first) : null,
  }
}

/** Opaque cursors from the server (`nextCursor`), or keyset cursors built from the rows with `keyset`. */
function cursorSource<T, F = unknown, Raw = PageResult<T>>(options: CursorSourceOptions<T, F, Raw>): PageSource<T, F> {
  const { afterParam = "cursor", beforeParam = "before", sizeParam = "limit", keyset } = options
  return {
    key: options.key,
    getId: options.getId,
    capabilities: { position: "cursor", total: "none", maxPageSize: options.maxPageSize },
    async fetchPage(request, context) {
      const position = cursorOf(request)
      const params = appendParams(new URLSearchParams(), options.params?.(request.filter))
      writeSort(params, request.sort, options.sortStyle, options.sortParam)
      if (position.cursor !== null)
        params.set(position.direction === "forward" ? afterParam : beforeParam, position.cursor)
      params.set(sizeParam, String(keyset ? request.size + 1 : request.size))
      const raw = await options.request({ params, query: params.toString(), request, signal: context.signal })
      const result = options.read ? options.read(raw, request) : (raw as PageResult<T>)
      if (!Array.isArray(result.items)) throw new TypeError("cursorSource expected { items }; pass `read`.")
      if (keyset) return keysetResult(result.items, request.size, position, keyset.cursor)
      return { ...result, hasMore: result.hasMore ?? (result.nextCursor ?? null) !== null }
    },
    ...(options.fetchTotal ? { fetchTotal: options.fetchTotal } : {}),
  }
}

/** A GraphQL connection as the Relay spec defines it. */
type RelayConnection<T> = {
  edges?: readonly ({ node: T; cursor?: string } | null)[] | null
  nodes?: readonly T[] | null
  pageInfo: { hasNextPage: boolean; hasPreviousPage: boolean; startCursor?: string | null; endCursor?: string | null }
  totalCount?: number | null
}

type RelayVariables = { first?: number; after?: string; last?: number; before?: string }

type RelayCall<F> = { variables: RelayVariables; request: PageRequest<F>; signal: AbortSignal }

type RelaySourceOptions<T, F, Raw> = {
  key: readonly unknown[]
  getId: (item: T) => string
  /** Runs the query with `variables` (`first`/`after` forward, `last`/`before` backward) and your filter and sort. */
  request: (call: RelayCall<F>) => Promise<Raw>
  /** Where the connection sits in the response: `(data) => data.repository.issues`. */
  connection?: (raw: Raw) => RelayConnection<T>
  maxPageSize?: number
  /** `"exact"` when the connection has `totalCount`. Default `"none"`. */
  total?: "exact" | "none"
  fetchTotal?: (filter: F, context: SourceContext) => Promise<number>
}

/** `first`/`after` and `last`/`before` over `edges` and `pageInfo`, with `totalCount` when the schema has one. */
function relaySource<T, F = unknown, Raw = RelayConnection<T>>(
  options: RelaySourceOptions<T, F, Raw>,
): PageSource<T, F> {
  return {
    key: options.key,
    getId: options.getId,
    capabilities: { position: "cursor", total: options.total ?? "none", maxPageSize: options.maxPageSize },
    async fetchPage(request, context) {
      const position = cursorOf(request)
      const variables: RelayVariables =
        position.direction === "forward"
          ? { first: request.size, ...(position.cursor === null ? {} : { after: position.cursor }) }
          : { last: request.size, ...(position.cursor === null ? {} : { before: position.cursor }) }
      const raw = await options.request({ variables, request, signal: context.signal })
      const connection = options.connection ? options.connection(raw) : (raw as RelayConnection<T>)
      if (typeof connection !== "object" || connection === null || typeof connection.pageInfo !== "object")
        throw new TypeError("relaySource expected a connection with `pageInfo`; pass `connection` to find it.")
      const items = connection.edges
        ? connection.edges.flatMap((edge) => (edge ? [edge.node] : []))
        : [...(connection.nodes ?? [])]
      const { pageInfo } = connection
      return {
        items,
        ...(typeof connection.totalCount === "number" ? { total: connection.totalCount } : {}),
        hasMore: pageInfo.hasNextPage,
        hasPrevious: pageInfo.hasPreviousPage,
        nextCursor: pageInfo.hasNextPage ? (pageInfo.endCursor ?? null) : null,
        prevCursor: pageInfo.hasPreviousPage ? (pageInfo.startCursor ?? null) : null,
      }
    },
    ...(options.fetchTotal ? { fetchTotal: options.fetchTotal } : {}),
  }
}

type LinkRelations = Record<string, string>

// RFC 8288: `<uri>; rel="next last"; title="x", <uri>; rel=prev`. A URI may hold commas and semicolons; parameter
// values may be quoted, with backslash escapes. Relation names are case-insensitive and one link may carry several.
function parseLinkHeader(header: string | null | undefined): LinkRelations {
  const links: LinkRelations = {}
  if (!header) return links
  let index = 0
  const length = header.length
  while (index < length) {
    const open = header.indexOf("<", index)
    if (open === -1) break
    const close = header.indexOf(">", open + 1)
    if (close === -1) break
    const uri = header.slice(open + 1, close).trim()
    index = close + 1
    const relations: string[] = []
    while (index < length) {
      while (index < length && /\s/.test(header.charAt(index))) index++
      if (header.charAt(index) !== ";") break
      index++
      const nameMatch = /^\s*([^\s=;,]+)\s*/.exec(header.slice(index))
      if (!nameMatch) break
      const name = (nameMatch[1] ?? "").toLowerCase()
      index += nameMatch[0].length
      let value = ""
      if (header.charAt(index) === "=") {
        index++
        while (index < length && /\s/.test(header.charAt(index))) index++
        if (header.charAt(index) === '"') {
          index++
          while (index < length && header.charAt(index) !== '"') {
            if (header.charAt(index) === "\\") index++
            value += header.charAt(index)
            index++
          }
          index++
        } else {
          const token = /^[^;,\s]*/.exec(header.slice(index))?.[0] ?? ""
          value = token
          index += token.length
        }
      }
      if (name === "rel") relations.push(...value.toLowerCase().split(/\s+/).filter(Boolean))
    }
    for (const relation of relations) links[relation] ??= uri
    const comma = header.indexOf(",", index)
    if (comma === -1) break
    index = comma + 1
  }
  return links
}

type LinkHeaderResponse = Response | { headers: Headers | { get(name: string): string | null }; body: unknown }

type LinkHeaderCall<F> = RestCall<F> & {
  /** The `next` or `prev` link to follow, in cursor mode; null for the first page. */
  url: string | null
}

type LinkHeaderSourceOptions<T, F> = {
  key: readonly unknown[]
  getId: (item: T) => string
  /** Fetches `call.url` when set, or your endpoint with `call.query`; return the `Response` itself. */
  request: (call: LinkHeaderCall<F>) => Promise<LinkHeaderResponse>
  /** The rows in the body. Default: the body, which must be an array. */
  read?: (body: unknown) => T[]
  params?: (filter: F) => ParamsInit
  sortStyle?: SortStyle
  sortParam?: string
  /** `"page"` (default) sends page numbers and reads them back from the links; `"cursor"` follows the links. */
  position?: "page" | "cursor"
  pageParam?: string
  sizeParam?: string
  base?: 0 | 1
  maxPageSize?: number
}

function pageInLink(link: string | undefined, pageParam: string) {
  if (link === undefined) return undefined
  const query = link.includes("?") ? link.slice(link.indexOf("?") + 1).split("#")[0] : ""
  const value = new URLSearchParams(query).get(pageParam)
  const page = value === null ? Number.NaN : Number(value)
  return Number.isInteger(page) ? page : undefined
}

async function bodyOf(response: LinkHeaderResponse) {
  if (typeof Response !== "undefined" && response instanceof Response) {
    if (!response.ok) throw new HttpError(response.status, response.statusText || undefined, response)
    return { headers: response.headers, body: (await response.json()) as unknown }
  }
  return response as Exclude<LinkHeaderResponse, Response>
}

/**
 * Paging from an RFC 8288 `Link` header, as GitHub and many REST APIs send it. With a `last` link on another page,
 * the total is an estimate (whole pages); on the last page it is exact.
 */
function linkHeaderSource<T, F = unknown>(options: LinkHeaderSourceOptions<T, F>): PageSource<T, F> {
  const { position = "page", pageParam = "page", sizeParam = "per_page", base = 1 } = options
  return {
    key: options.key,
    getId: options.getId,
    capabilities: { position, total: position === "page" ? "estimate" : "none", maxPageSize: options.maxPageSize },
    async fetchPage(request, context) {
      const params = appendParams(new URLSearchParams(), options.params?.(request.filter))
      writeSort(params, request.sort, options.sortStyle, options.sortParam)
      params.set(sizeParam, String(request.size))
      let url: string | null = null
      let page = 1
      if (position === "page") {
        if (!isPagePosition(request.position)) throw new TypeError("This source pages by number; it got a cursor.")
        page = Math.max(1, Math.trunc(request.position.page))
        params.set(pageParam, String(page - 1 + base))
      } else url = cursorOf(request).cursor
      const response = await options.request({ params, query: params.toString(), request, signal: context.signal, url })
      const { headers, body } = await bodyOf(response)
      const items = options.read ? options.read(body) : body
      if (!Array.isArray(items)) throw new TypeError("linkHeaderSource expected an array body; pass `read`.")
      const links = parseLinkHeader(headers.get("link"))
      const result: PageResult<T> = {
        items: items as T[],
        hasMore: links.next !== undefined,
        hasPrevious: links.prev !== undefined || links.previous !== undefined,
      }
      if (position === "cursor")
        return { ...result, nextCursor: links.next ?? null, prevCursor: links.prev ?? links.previous ?? null }
      const lastPage = pageInLink(links.last, pageParam)
      if (links.next === undefined) return { ...result, total: (page - 1) * request.size + items.length }
      if (lastPage !== undefined) return { ...result, totalEstimate: (lastPage - base + 1) * request.size }
      return result
    },
  }
}

